<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>New York Skyline - Creative SVG</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            background: linear-gradient(to bottom, #0f172a 0%, #1e293b 50%, #334155 100%);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .skyline-container {
            width: 90vw;
            max-width: 1200px;
            position: relative;
        }

        svg {
            display: block;
            width: 100%;
            height: auto;
            filter: drop-shadow(0 0 30px rgba(94, 165, 250, 0.4));
        }

        /* Interactive hover effects */
        .hover-highlight {
            transition: fill 0.3s ease, opacity 0.3s ease;
            cursor: pointer;
        }

        .hover-highlight:hover {
            fill: #fbbf24 !important;
            filter: drop-shadow(0 0 15px rgba(251, 191, 36, 0.8));
        }

        /* Subtle animation for the helipad helicopter */
        @keyframes hoverEffect {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-2px); }
        }

        .helicopter-hover {
            animation: hoverEffect 3s infinite ease-in-out;
        }

        /* Floating clouds */
        @keyframes floatClouds {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-10px); }
            75% { transform: translateX(10px); }
        }

        .cloud-floating {
            animation: floatClouds 8s infinite ease-in-out;
        }
    </style>
</head>
<body>
    <div class="skyline-container">
        <svg viewBox="0 0 1200 600" xmlns="http://www.w3.org/2000/svg">
            <!-- Definitions for gradients and filters -->
