                <filter id="glow-filter" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blur"/>
                    <feColorMatrix in="blur" type="matrix">
                        <se xlink:href="#moon-glow" result="moon-blur"/>
                    </feColorMatrix>
                </filter>

                <!-- Building gradient for 3D effect -->
                <linearGradient id="building-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" style="stop-color:#475569;stop-opacity:1" />
                    <stop offset="50%" style="stop-color:#334155;stop-opacity:1" />
                    <stop offset="100%" style="stop-color:#1e293b;stop-opacity:1" />
                </linearGradient>

                <!-- Windows highlight gradient -->
                <linearGradient id="window-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" style="stop-color:#fbbf24;stop-opacity:0.8" />
                    <stop offset="50%" style="stop-color:#f59e0b;stop-opacity:0.6" />
                    <stop offset="100%" style="stop-color:#d97706;stop-opacity:0.4" />
                </linearGradient>

                <!-- Water reflection gradient -->
