                    <stop offset="50%" style="stop-color:#0ea5e9;stop-opacity:0.4" />
                    <stop offset="100%" style="stop-color:#0284c7;stop-opacity:0.5" />
                </linearGradient>

                <!-- Moon glow filter -->
                <filter id="moon-glow">
                    <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blur"/>
                </filter>
