            <!-- Background moon with subtle glow -->
            <circle cx="1050" cy="80" r="40" fill="#fef3c7" filter="url(#moon-glow)">
                <animate attributeName="r" values="40;42;40" dur="6s" repeatCount="indefinite" />
            </circle>

